import {
    domAdapter
} from "../../core/m_dom_adapter";
export const isFocusLost = () => {
    const activeElement = domAdapter.getActiveElement();
    const body = domAdapter.getBody();
    return !activeElement || activeElement === body || !body.contains(activeElement)
};
